static double memory_test(void){SIZE_T size=128*1024*1024;unsigned char *a=VirtualAlloc(NULL,size,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE),*b=VirtualAlloc(NULL,size,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE);if(!a||!b){if(a)VirtualFree(a,0,MEM_RELEASE);if(b)VirtualFree(b,0,MEM_RELEASE);return 0;}memset(a,0x59,size);memset(b,0x37,size);double start=now();unsigned count=0;volatile unsigned char check=0;do{{void *(*volatile copy_fn)(void*,const void*,size_t)=memcpy;copy_fn(b,a,size);}check^=b[count%size];unsigned char *t=a;a=b;b=t;count++;}while(now()-start<1.2);double elapsed=now()-start;VirtualFree(a,0,MEM_RELEASE);VirtualFree(b,0,MEM_RELEASE);return count*(double)size/1048576./elapsed+(check==255?0.:0.);}
static void disk_test(const wchar_t *path,double *write_speed,double *read_speed){const DWORD block=1024*1024;unsigned char *buffer=VirtualAlloc(NULL,block,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE);if(!buffer)return;for(DWORD i=0;i<block;i++)buffer[i]=(unsigned char)(i*131+17);HANDLE file=CreateFileW(path,GENERIC_READ|GENERIC_WRITE,0,NULL,CREATE_NEW,FILE_ATTRIBUTE_TEMPORARY|FILE_FLAG_DELETE_ON_CLOSE|FILE_FLAG_NO_BUFFERING|FILE_FLAG_WRITE_THROUGH,NULL);if(file==INVALID_HANDLE_VALUE){VirtualFree(buffer,0,MEM_RELEASE);return;}DWORD bytes;int ok=1;double start=now();for(int i=0;i<256;i++)if(!WriteFile(file,buffer,block,&bytes,NULL)||bytes!=block){ok=0;break;}if(ok&&FlushFileBuffers(file))*write_speed=256./(now()-start);LARGE_INTEGER zero;zero.QuadPart=0;if(ok&&SetFilePointerEx(file,zero,NULL,FILE_BEGIN)){start=now();for(int i=0;i<256;i++)if(!ReadFile(file,buffer,block,&bytes,NULL)||bytes!=block){ok=0;break;}if(ok)*read_speed=256./(now()-start);}CloseHandle(file);VirtualFree(buffer,0,MEM_RELEASE);}
