int wmain(int argc,wchar_t **argv){QueryPerformanceFrequency(&frequency);SetPriorityClass(GetCurrentProcess(),BELOW_NORMAL_PRIORITY_CLASS);if(argc!=2)return 2;SYSTEM_INFO info;GetSystemInfo(&info);unsigned threads=info.dwNumberOfProcessors;if(threads>64)threads=64;if(threads<1)threads=1;MEMORYSTATUSEX mem={0};mem.dwLength=sizeof(mem);GlobalMemoryStatusEx(&mem);double single=cpu(1),multi=cpu(threads),memory=mem.ullAvailPhys>512ULL*1024*1024?memory_test():0,write_speed=0,read_speed=0;ULARGE_INTEGER available,total,freebytes;if(GetDiskFreeSpaceExW(NULL,&available,&total,&freebytes)&&available.QuadPart>512ULL*1024*1024)disk_test(argv[1],&write_speed,&read_speed);char gpu_name[512]="";double gpu=gpu_test(gpu_name,sizeof(gpu_name));printf("{\"cpu_single_mloops\":%.3f,\"cpu_multi_mloops\":%.3f,\"threads\":%u,\"memory_mib_s\":%.2f,\"disk_write_mib_s\":%.2f,\"disk_read_mib_s\":%.2f,\"gpu_ms\":%.5f,\"gpu_name\":",single,multi,threads,memory,write_speed,read_speed,gpu);json_string(gpu_name);printf("}\n");return 0;}
